#!/usr/bin/env python3
"""JATS XML -> sectioned plain text (for review evidence packs)."""
import sys
import re
import xml.etree.ElementTree as ET

SRC = sys.argv[1] if len(sys.argv) > 1 else "fulltext.xml"
tree = ET.parse(SRC)
root = tree.getroot()

def text_of(el, strip_refs=False):
    if el is None:
        return ""
    parts = []
    for node in el.iter():
        tag = node.tag
        if tag in ("xref",):
            continue
        if node.text:
            parts.append(node.text)
        if node.tail:
            parts.append(node.tail)
    return re.sub(r"\s+", " ", "".join(parts)).strip()

def sec_title(sec):
    t = sec.find("title")
    return text_of(t) if t is not None else "(untitled)"

out = []
front = root.find("front")
am = front.find("article-meta") if front is not None else None

title = text_of(am.find("title-group/article-title")) if am is not None else ""
doi = pmid = pmcid = ""
for aid in am.findall("article-id"):
    if aid.get("pub-id-type") == "doi": doi = text_of(aid)
    if aid.get("pub-id-type") == "pmid": pmid = text_of(aid)
    if aid.get("pub-id-type") == "pmcid": pmcid = text_of(aid)

out.append(f"# FRONT\nTITLE: {title}\nDOI: {doi}\nPMID: {pmid}\nPMCID: {pmcid}")

# authors/affiliations
contribs = []
for c in am.findall("contrib-group/contrib"):
    nm = c.find("name")
    if nm is not None:
        contribs.append(text_of(nm.find("surname")) + " " + text_of(nm.find("given-names")))
out.append("AUTHORS: " + "; ".join(contribs))

# abstract
for ab in am.findall("abstract"):
    out.append("\n# ABSTRACT")
    for sec in ab.findall("sec"):
        out.append(f"[{sec_title(sec)}]")
        for p in sec.findall("p"):
            out.append(text_of(p))

body = root.find("body")
def walk(el, depth=0, section=None):
    for child in el:
        if child.tag == "sec":
            walk(child, depth + 1)
        elif child.tag in ("p", "title"):
            txt = text_of(child)
            if child.tag == "title":
                out.append("\n" + "#" * min(depth + 1, 4) + f" {txt}  [{child.get('id') or (el.get('id') or '')}]")
            else:
                out.append(f"[{section or ''}][{child.get('id') or 'p'}] {txt}")
        elif child.tag in ("table-wrap", "fig", "list", "disp-quote", "supplementary-material"):
            walk(child, depth, section)
        elif child.tag == "label":
            out.append(f"\n[{child.get('id') or ''}] {text_of(child)}")

if body is not None:
    for sec in body:
        if sec.tag == "sec":
            out.append("\n===== SECTION: %s =====" % sec_title(sec))
            sid = sec.get("id") or sec_title(sec)
            for child in sec.iter():
                if child.tag == "sec":
                    out.append(f"\n--- SUBSECTION [{child.get('id') or ''}]: {sec_title(child)} ---")
                elif child.tag == "p":
                    out.append(f"[{sid}][{child.get('id') or 'p'}] {text_of(child)}")
                elif child.tag == "table-wrap":
                    lbl = child.find("label")
                    cap = child.find("caption")
                    out.append(f"\n[TABLE {text_of(lbl)}] caption: {text_of(cap)}")
                    tbl = child.find("table")
                    if tbl is not None:
                        for tr in tbl.iter("tr"):
                            cells = []
                            for td in tr:
                                cells.append(text_of(td))
                            out.append(" | ".join(cells))
                elif child.tag == "fig":
                    lbl = child.find("label")
                    cap = child.find("caption")
                    g = child.find(".//graphic")
